"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[5394],{3648:(e,a,n)=>{n.r(a),n.d(a,{data:()=>t});const t={key:"v-1c8a9308",path:"/hu_HU/troubleshooting.html",title:"Hibaelhárítás",lang:"hu-HU",frontmatter:{},excerpt:"",headers:[{level:2,title:"Unlaunch",slug:"unlaunch",children:[{level:3,title:"Az Unlaunch lefagy a MISMATCH IN FAT COPIES üzenetnél?",slug:"az-unlaunch-lefagy-a-mismatch-in-fat-copies-uzenetnel",children:[]},{level:3,title:'Nincs hang vagy boot képernyő, amikor a "LAUNCHER" kerül indításra az Unlaunch-csel',slug:"nincs-hang-vagy-boot-kepernyo-amikor-a-launcher-kerul-inditasra-az-unlaunch-csel",children:[]}]}],filePathRelative:"hu_HU/troubleshooting.md",git:{updatedTime:16354756e5,contributors:[{name:"Pk11",email:"epicpkmn11@outlook.com",commits:1}]}}},8525:(e,a,n)=>{n.r(a),n.d(a,{default:()=>i});const t=(0,n(6252).uE)('<h1 id="hibaelharitas" tabindex="-1"><a class="header-anchor" href="#hibaelharitas" aria-hidden="true">#</a> Hibaelhárítás</h1><h2 id="unlaunch" tabindex="-1"><a class="header-anchor" href="#unlaunch" aria-hidden="true">#</a> Unlaunch</h2><h3 id="az-unlaunch-lefagy-a-mismatch-in-fat-copies-uzenetnel" tabindex="-1"><a class="header-anchor" href="#az-unlaunch-lefagy-a-mismatch-in-fat-copies-uzenetnel" aria-hidden="true">#</a> Az Unlaunch lefagy a <code>MISMATCH IN FAT COPIES</code> üzenetnél?</h3><p>A twlnf-nek van egy kritikus hibája, amikor nem frissíti megfelelően az egész NAND-ot a módosítása után, ami bizonyos homebrew-ok esetén (mint példul az Unlaunch telepítő) hibát dob.</p><p>Habár javítható, a metódus, ahogy ez megtehető, nem kőbe vésett és változik a különböző rendszereken. Az egyik metódus, hogy törölj minden DSiWare-t ami a twlnf-en keresztül lett telepítve a múltban, de azt is jelentette valaki, hogy a mozgatása <em>minden</em> DSiWare-nek az SD kártyára, majd vissza segített bizonyos esetekben.</p><p>Ha korábban downgrade-elted a rendszert, a vissza frissítése v1.4.5-re (vagy v1.4.6-ra, ha a DS régiód kínai vagy koreai) is segíthet ezen a hibán.</p><h3 id="nincs-hang-vagy-boot-kepernyo-amikor-a-launcher-kerul-inditasra-az-unlaunch-csel" tabindex="-1"><a class="header-anchor" href="#nincs-hang-vagy-boot-kepernyo-amikor-a-launcher-kerul-inditasra-az-unlaunch-csel" aria-hidden="true">#</a> Nincs hang vagy boot képernyő, amikor a &quot;LAUNCHER&quot; kerül indításra az Unlaunch-csel</h3><p>Az Unlaunch fejlesztője (nocash) szándékosan kipatchelte alapértelmezésként háttérzenét és a boot képernyőt. Visszaszerezheted ezeket az effekteket az <a href="/installing-unlaunch">Unlaunch újratelepítésével</a> a TWiLight Menu++-n keresztül.</p>',8),l={},i=(0,n(3744).Z)(l,[["render",function(e,a){return t}]])},3744:(e,a)=>{a.Z=(e,a)=>{for(const[n,t]of a)e[n]=t;return e}}}]);